css:
/* カードで写真に食い込ませる（影ゼロ） */
.wrap{display:grid; grid-template-columns:1fr 1fr; align-items:center}
.wrap .card{grid-area:1/1; z-index:2; background:#fff;
  border-radius:0; box-shadow:none; padding:26px 30px; margin-right:-20px}
.wrap figure{grid-area:1/2; z-index:1}

/* 全幅断ち落としの帯＋左マージンまで寄せたカード */
.photo{width:100vw; margin-left:calc(50% - 50vw); height:450px; object-fit:cover; display:block}
.band{position:relative}
.band .card{position:absolute; left:30px; top:145px; width:41%;
  background:#fff; border-radius:20px; padding:36px; box-shadow:0 8px 34px rgba(0,0,0,.10)}

/* 正円で継ぎ目を隠す */
.disc{width:400px; aspect-ratio:1; border-radius:50%; background:#1b3a55;
  margin-left:-140px; align-self:center; position:relative; z-index:2;
  display:grid; place-content:center; color:#fff}

/* 帯の端を写真の弧の下へ潜らせ、始点を見せない */
h2{position:relative; z-index:0; width:min(58%,640px);
  background:linear-gradient(90deg,#e8f0d5,#d3ebe9);
  margin-left:-160px; padding:10px 24px 12px 180px}
figure{position:relative; z-index:2}
